/// Gizmo write-back: drags ran on an EVALUATED copy; changed channels go
/// back as a key at the current frame when the channel is animated (or
/// autokey is on), else straight into the authored param. Unanimated
/// channels evaluate to their authored values, so the direct write is exact.
/// Write an rgb triple back from a viewer HUD: keyed when the channel is
/// animated (or autokey is on), authored otherwise, and never over a
/// cable-driven channel. The ganged axes move all three at once, so they
/// cannot go through the one-channel path above.
fn write_hud_triple(
    graph: &mut editor::EditorGraph,
    node: u64,
    chans: &[anim::Channel],
    v: [f32; 3],
    t: u64,
    autokey: bool,
    driven: &[(u64, anim::Channel)],
) {
    let Some(n) = graph.node_mut(node) else { return };
    let editor::ENode { kind, anim, .. } = n;
    for (i, ch) in chans.iter().take(3).enumerate() {
        if driven.contains(&(node, *ch)) || anim::is_locked(anim, *ch) {
            continue;
        }
        let animated = anim.get(ch).is_some_and(|c| !c.keys.is_empty());
        if animated || autokey {
            anim.entry(*ch).or_default().set_key_shown(t, v[i]);
        } else {
            anim::set(kind, *ch, v[i]);
        }
    }
}

fn keyed_write_back(
    anim: &mut std::collections::BTreeMap<anim::Channel, anim::AnimCurve>,
    authored: &mut NodeKind,
    before: &NodeKind,
    after: &NodeKind,
    // Any frame, not only the playhead's: dragging a key ON a motion path
    // writes at THAT key's frame, which may be a sub-frame one.
    t: impl anim::AtFrame,
    chans: &[anim::Channel],
    autokey: bool,
    driven: &[(u64, anim::Channel)],
    node: u64,
) {
    for ch in chans {
        // A cable-driven channel ignores gizmo edits: the patch overrides
        // them every frame, and "patched value + drag delta" would land a
        // surprise in the authored data.
        if driven.contains(&(node, *ch)) {
            continue;
        }
        // LOCKED: this channel takes no keys and no value. Every write path
        // in the app comes through here — rows, gizmos, HUD sliders, autokey
        // — so locking translate.x pins it against all of them while
        // translate.y keeps animating.
        if anim::is_locked(anim, *ch) {
            continue;
        }
        let (Some(b), Some(a)) = (anim::get(before, *ch), anim::get(after, *ch)) else {
            continue;
        };
        if a == b {
            continue;
        }
        let animated = anim.get(ch).is_some_and(|c| !c.keys.is_empty());
        if animated || autokey {
            anim.entry(*ch).or_default().set_key_shown(t, a);
        } else {
            anim::set(authored, *ch, a);
        }
    }
}

/// A CornerPin group edit, computed ABSOLUTELY from its press: the pins as
/// they were (`start`, the quad being edited, normalised), which of them move,
/// the press on screen and a pivot in node pixels. Pins are keyable channels,
/// and a per-frame delta on an animated channel moves by the last frame's
/// step alone (the gizmo trap in CLAUDE.md).
#[derive(Clone)]
struct PinGrab {
    node: u64,
    mode: PinMode,
    origin: egui::Pos2,
    pivot: egui::Vec2,
    start: [[f32; 2]; 4],
    moving: [bool; 4],
    /// R held: the cursor's angle round the pivot once it left the dead
    /// zone (the pivot IS the press, so the press has no angle).
    a0: Option<f32>,
    /// Started by E / R / T held: draws the temporary pivot.
    by_key: bool,
    /// The RATED pointer (screen): it moves by the real pointer's travel
    /// times the held Z/X/C/V rate, read live each frame, and every edit is
    /// computed from it. Still absolute from the snapshot, so an animated
    /// pin keys cleanly, and a key let go mid-drag does not snap.
    vp: egui::Pos2,
    /// The real pointer last frame, for that travel.
    last: egui::Pos2,
}

#[derive(Clone, Copy, PartialEq)]
enum PinMode {
    /// A pin, the box centre or T held: follow the pointer.
    Move,
    /// A box handle: scale about `pivot` along the axes the handle drives.
    Scale(bool, bool),
    /// The box's knob: turn about `pivot` by the angle the pointer sweeps.
    Rotate,
    /// E held: uniform scale about the press, by horizontal travel.
    KeyScale,
    /// R held: turn about the press.
    KeyRotate,
}

/// A structural spline edit, carried from the gizmo to the write-back so
/// the per-point curves can follow their points. `Removed` carries the
/// point count from BEFORE the removal.
#[derive(Clone, Copy)]
enum SplineEdit {
    Inserted(usize),
    Removed(usize, usize),
}

/// Slide a point pick through a structural edit, the way
/// `anim::spline_point_inserted` / `_removed` slide the curves. The new
/// point does not join the pick: shift-clicking a run of points in should
/// not keep growing the group box.
fn remap_spline_sel(sel: &mut std::collections::BTreeSet<usize>, e: SplineEdit) {
    let mut out = std::collections::BTreeSet::new();
    match e {
        SplineEdit::Inserted(at) => {
            for k in sel.iter() {
                out.insert(if *k >= at { k + 1 } else { *k });
            }
        }
        SplineEdit::Removed(at, _) => {
            for k in sel.iter() {
                match (*k).cmp(&at) {
                    std::cmp::Ordering::Less => out.insert(*k),
                    std::cmp::Ordering::Greater => out.insert(k - 1),
                    std::cmp::Ordering::Equal => false,
                };
            }
        }
    }
    *sel = out;
}

/// Spline write-back. Same rules as `keyed_write_back` — patched channels
/// are left alone, a key lands when the channel is animated or autokey is
/// on — except that a spline keys as ONE shape: touch any control point and
/// every point's position lands on this frame (feather is its own group).
/// Keying only the point under the cursor is how a rotoshape turns into a
/// different shape two frames later.
#[allow(clippy::too_many_arguments)]
fn spline_keyed_write_back(
    anim: &mut anim::Anim,
    authored: &mut NodeKind,
    before: &NodeKind,
    after: &NodeKind,
    t: u64,
    autokey: bool,
    driven: &[(u64, anim::Channel)],
    node: u64,
) {
    let NodeKind::Spline(sp) = after else { return };
    let n = sp.points.len();
    for group in [
        anim::spline_shape(n),
        anim::spline_feather(n),
        vec![anim::Channel::SplineExpand],
    ] {
        let live: Vec<anim::Channel> = group
            .into_iter()
            .filter(|ch| !driven.contains(&(node, *ch)) && !anim::is_locked(anim, *ch))
            .collect();
        let touched = live
            .iter()
            .any(|ch| anim::get(before, *ch) != anim::get(after, *ch));
        if !touched {
            continue;
        }
        let animated = live
            .iter()
            .any(|ch| anim.get(ch).is_some_and(|c| !c.keys.is_empty()));
        for ch in live {
            let Some(v) = anim::get(after, ch) else { continue };
            if animated || autokey {
                anim.entry(ch).or_default().set_key_shown(t, v);
            } else {
                anim::set(authored, ch, v);
            }
        }
    }
}

/// Migrations for older setup files. Merge used to be a unit variant
/// (serialized as the bare string "Merge"); it now carries an op.
/// A Time Remap as a picture: the source in/out on a bar above, the target
/// in/out on a bar below (the Load panel's bar, both draggable), and a line
/// from each target frame to the source frame it reads.
///
/// Each bar has its OWN view, with a frame ruler, navigated with the
/// viewer's and graph's hands (`nav::bar_nav`: wheel / pinch / ctrl+MMB
/// zoom, MMB / alt+LMB / two fingers pan) plus a plain drag on the ruler;
/// a double-click on the bar fits it. So a slip of a thousand frames still shows both ends
/// close up, and the lines run between the two views wherever they sit.
///
/// The first and last lines are the in and out PAIRS: click one to switch
/// it off. Out off = no retime, a slip putting source in on target in; in
/// off = the same through the outs. Only one can be off at a time.
fn remap_bars(
    ui: &mut egui::Ui,
    node: u64,
    rp: &mut engine::graph::RangeRemapParams,
    input: Option<(u64, u64)>,
    script: (i64, i64),
    cur_t: i64,
) -> Option<i64> {
    use imfram::widgets::{span::{fit, x_of}, span_bar, SpanOpts};
    // Tall enough for a frame number at each end of a near-vertical line.
    const GAP: f32 = 64.0;
    // A reversed pair (out before in) draws as its span; the order is kept.
    let norm = |p: (f32, f32)| {
        let (a, b) = (p.0.round() as i64, p.1.round() as i64);
        ((a.min(b), a.max(b)), a > b)
    };
    let (mut s, s_rev) = norm(rp.src);
    let (mut d, d_rev) = norm(rp.dst);
    let solid = input.map(|(a, b)| (a as i64, b as i64));
    let (k, b) = rp.affine();
    let read = |t: f64| k as f64 * t + b as f64;
    let on_dst = (d.0..=d.1).contains(&cur_t);

    // The two views, kept per node; first sight fits each to its own span.
    let vid = |w: &str| ui.make_persistent_id(("remap-view", node, w));
    let (sid, did) = (vid("src"), vid("dst"));
    let get = |id: egui::Id, span: (i64, i64), solid: Option<(i64, i64)>| {
        ui.data(|m| m.get_temp::<(f64, f64)>(id)).unwrap_or_else(|| {
            let (a, b) = fit(span, solid);
            (a as f64, b as f64)
        })
    };
    let mut sv = get(sid, s, solid);
    let mut dv = get(did, d, None);
    let round = |v: (f64, f64)| (v.0.round() as i64, v.1.round() as i64);
    // Both spans in one view: what "lock" resets to, and what R / a
    // double-click frames while locked.
    let both = {
        let (a, b) = fit((s.0.min(d.0), s.1.max(d.1)), None);
        (a as f64, b as f64)
    };
    // Locked: one view for both bars, so they pan and zoom together.
    let lock_id = vid("lock");
    let mut locked = ui.data(|m| m.get_temp::<bool>(lock_id)).unwrap_or(false);
    let r_down = !ui.ctx().egui_wants_keyboard_input()
        && !keymap::capturing()
        && ui.input(|i| keymap::pressed(i, keymap::Act::TimelineFrame));
    let hover_pos = ui.ctx().pointer_hover_pos();
    let hovered = |r: egui::Rect| hover_pos.is_some_and(|p| r.contains(p));

    // --- source: ruler, bar ------------------------------------------------
    ui.horizontal(|ui| {
        ui.weak("source");
        ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
            if ui
                .add(egui::Button::new(egui::RichText::new("lock views").small()).selected(locked))
                .on_hover_text(
                    "one view for both bars, reset to show both spans: they pan \
                     and zoom together · R over a bar frames its in/out",
                )
                .clicked()
            {
                locked = !locked;
                if locked {
                    sv = both;
                    dv = both;
                }
            }
        });
    });
    let s_ruler = remap_ruler(ui, &mut sv, true);
    let so = span_bar(
        ui,
        ("remap-src", node),
        &mut s,
        SpanOpts {
            view: Some(round(sv)),
            solid,
            marker: on_dst.then(|| read(cur_t as f64).round() as i64),
            labels: true,
            hint: Some(
                "the upstream frames this plays · grey = the input's frames · \
                 click puts the playhead on the frame that reads it\n\
                 wheel or ctrl+MMB zooms · MMB, alt-drag or the ruler pans · R or double-click frames it",
            ),
            ..Default::default()
        },
    );
    let s_area = so.rect.union(s_ruler);
    crate::nav::bar_nav(ui, sid.with("nav"), s_area, &mut sv);
    if so.double_clicked || (r_down && hovered(s_area)) {
        sv = if locked {
            both
        } else {
            let (a, b) = fit(s, None);
            (a as f64, b as f64)
        };
    }
    if locked {
        dv = sv;
    }

    // --- the lines ---------------------------------------------------------
    let (gap, gap_resp) =
        ui.allocate_exact_size(egui::vec2(so.rect.width(), GAP), egui::Sense::click());

    // --- target: bar, ruler ------------------------------------------------
    let dout = span_bar(
        ui,
        ("remap-dst", node),
        &mut d,
        SpanOpts {
            view: Some(round(dv)),
            solid: Some(script),
            marker: Some(cur_t),
            labels: true,
            color: Some(theme::range_load()),
            hint: Some(
                "where they play on this timeline · grey = the comp's script range · \
                 click moves the playhead\n\
                 wheel or ctrl+MMB zooms · MMB, alt-drag or the ruler pans · R or double-click frames it",
            ),
            ..Default::default()
        },
    );
    // The speed, written in the middle of the target span (of the part on
    // screen): 50%, -100% for a reverse, or the slip with a pair off.
    {
        let lo = x_of(dout.rect, dout.view, d.0 as f64).max(dout.rect.min.x);
        let hi = x_of(dout.rect, dout.view, d.1 as f64 + 1.0).min(dout.rect.max.x);
        let txt = if rp.in_off || rp.out_off {
            let (_, b) = rp.affine();
            format!("slip {:+}", b.round() as i64)
        } else {
            let pct = k * 100.0;
            if (pct - pct.round()).abs() < 0.05 { format!("{pct:.0}%") } else { format!("{pct:.1}%") }
        };
        let painter = ui.painter_at(dout.rect);
        let g = painter.layout_no_wrap(txt, egui::FontId::monospace(10.0), ui.visuals().strong_text_color());
        // Clear of the end labels (about five digits each side).
        if hi - lo > g.size().x + 90.0 {
            let c = egui::pos2((lo + hi) * 0.5, dout.rect.center().y);
            painter.galley(c - g.size() * 0.5, g, egui::Color32::WHITE);
        }
    }
    let d_ruler = remap_ruler(ui, &mut dv, false);
    let d_area = dout.rect.union(d_ruler);
    crate::nav::bar_nav(ui, did.with("nav"), d_area, &mut dv);
    if dout.double_clicked || (r_down && hovered(d_area)) {
        dv = if locked {
            both
        } else {
            let (a, b) = fit(d, None);
            (a as f64, b as f64)
        };
    }
    if locked {
        sv = dv;
    }
    ui.weak("target");

    // Lines: from the target frame's cell centre to the source frame it
    // reads, each end in its own bar's view.
    let (svr, dvr) = (so.view, dout.view);
    let (y0, y1) = (gap.min.y, gap.max.y);
    let seg = |src: f64, dst: f64| {
        (
            egui::pos2(x_of(so.rect, svr, src + 0.5), y0),
            egui::pos2(x_of(dout.rect, dvr, dst + 0.5), y1),
        )
    };
    let painter = ui.painter_at(gap.expand2(egui::vec2(0.0, 1.0)));
    let v = ui.visuals().clone();
    let faint = egui::Stroke::new(1.0, v.weak_text_color().gamma_multiply(0.6));

    // In-between lines, about one per 14 px of target bar, over the part
    // of the target span that is on screen.
    let px_per = dout.rect.width() as f64 / ((dvr.1 - dvr.0 + 1).max(1) as f64);
    let step = nice_step(14.0 / px_per.max(1e-6)).max(1);
    let lo = d.0.max(dvr.0);
    let hi = d.1.min(dvr.1);
    let mut t = (lo.div_euclid(step) + 1) * step;
    while t < hi {
        let (a, c) = seg(read(t as f64), t as f64);
        painter.line_segment([a, c], faint);
        t += step;
    }

    // The ends: the pairs themselves, click to switch off.
    let pairs = [
        (seg(rp.src.0 as f64, rp.dst.0 as f64), rp.in_off),
        (seg(rp.src.1 as f64, rp.dst.1 as f64), rp.out_off),
    ];
    let ptr = gap_resp.hover_pos();
    let near = |(a, c): (egui::Pos2, egui::Pos2)| {
        ptr.map(|p| egui::Rect::from_two_pos(a, c).expand(6.0).contains(p)
            && dist_to_segment(p, a, c) <= 6.0)
            .unwrap_or(false)
    };
    let hot = [near(pairs[0].0), near(pairs[1].0)];
    let on_col = theme::range_load().lerp_to_gamma(egui::Color32::WHITE, 0.35);
    // A labelled line: the source frame at its top end and the target frame
    // at its bottom, each written ALONG the line (turned to read left to
    // right), the line itself running between them: 1425 ——— 1924.
    let font = egui::FontId::monospace(9.0);
    let frame_txt = |f: f64| {
        if (f - f.round()).abs() < 0.005 { format!("{}", f.round() as i64) } else { format!("{f:.2}") }
    };
    let labelled = |a: egui::Pos2, c: egui::Pos2, top: String, bottom: String, stroke: egui::Stroke, dashed: bool| {
        let d = c - a;
        let len = d.length();
        if len < 1.0 {
            return;
        }
        let dir = d / len;
        // Reading direction: never upside down.
        let read_dir = if dir.x < 0.0 { -dir } else { dir };
        let angle = read_dir.y.atan2(read_dir.x);
        let col = stroke.color;
        let gt = ui.painter().layout_no_wrap(top, font.clone(), col);
        let gb = ui.painter().layout_no_wrap(bottom, font.clone(), col);
        const PAD: f32 = 3.0;
        // Each label covers [p0, p1] along the line; its left-middle (in
        // reading order) sits at whichever end reads first.
        let place = |g: std::sync::Arc<egui::Galley>, p0: egui::Pos2, p1: egui::Pos2| {
            let left_mid = if read_dir == dir { p0 } else { p1 };
            let h = g.size().y;
            let (sn, cs) = angle.sin_cos();
            // The galley's own (0, h/2) turned by the angle.
            let off = egui::vec2(-sn * h * 0.5, cs * h * 0.5);
            painter.add(egui::epaint::TextShape::new(left_mid - off, g, col).with_angle(angle));
        };
        let (wt, wb) = (gt.size().x, gb.size().x);
        let fits = wt + wb + 4.0 * PAD + 6.0 <= len;
        let (l0, l1) = if fits {
            let t0 = a + dir * PAD;
            let t1 = t0 + dir * wt;
            place(gt, t0, t1);
            let b1 = c - dir * PAD;
            let b0 = b1 - dir * wb;
            place(gb, b0, b1);
            (t1 + dir * PAD, b0 - dir * PAD)
        } else {
            (a, c)
        };
        if dashed {
            painter.extend(egui::Shape::dashed_line(&[l0, l1], stroke, 4.0, 3.0));
        } else {
            painter.line_segment([l0, l1], stroke);
        }
    };
    let pair_frames = [(rp.src.0, rp.dst.0), (rp.src.1, rp.dst.1)];
    for (i, ((a, c), off)) in pairs.iter().enumerate() {
        let w = if hot[i] { 2.5 } else { 1.5 };
        let (fs, fd) = pair_frames[i];
        let (top, bottom) = (frame_txt(fs as f64), frame_txt(fd as f64));
        if *off {
            let col = v.weak_text_color().gamma_multiply(if hot[i] { 1.0 } else { 0.7 });
            labelled(*a, *c, top, bottom, egui::Stroke::new(w, col), true);
        } else {
            labelled(*a, *c, top, bottom, egui::Stroke::new(w, on_col), false);
        }
    }
    if on_dst {
        let fs = read(cur_t as f64);
        let (a, c) = seg(fs, cur_t as f64);
        labelled(a, c, frame_txt(fs), frame_txt(cur_t as f64), egui::Stroke::new(1.5, v.strong_text_color()), false);
    }
    let which = if hot[0] { Some(0) } else if hot[1] { Some(1) } else { None };
    if let Some(i) = which {
        ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
        let off = if i == 0 { rp.in_off } else { rp.out_off };
        let name = if i == 0 { "in" } else { "out" };
        let tip = if off {
            format!("the {name} pair is off: click to retime between in and out again")
        } else {
            format!(
                "click to switch the {name} pair off: no retime, a slip that puts \
                 source {other} on target {other}",
                other = if i == 0 { "out" } else { "in" }
            )
        };
        let gap_resp = gap_resp.on_hover_text(tip);
        if gap_resp.clicked() {
            // One pair always holds: switching one off turns the other on.
            if i == 0 {
                rp.in_off = !rp.in_off;
                if rp.in_off {
                    rp.out_off = false;
                }
            } else {
                rp.out_off = !rp.out_off;
                if rp.out_off {
                    rp.in_off = false;
                }
            }
        }
    }

    let unnorm = |p: (i64, i64), rev: bool| {
        if rev { (p.1 as f32, p.0 as f32) } else { (p.0 as f32, p.1 as f32) }
    };
    if so.changed {
        rp.src = unnorm(s, s_rev);
    }
    if dout.changed {
        rp.dst = unnorm(d, d_rev);
    }
    ui.data_mut(|m| {
        m.insert_temp(sid, sv);
        m.insert_temp(did, dv);
        m.insert_temp(lock_id, locked);
    });
    // A click on a bar drives the playhead: on the target, that frame; on
    // the source, the target frame that reads it (none when held still).
    if let Some(f) = dout.clicked {
        return Some(f.floor() as i64);
    }
    if let Some(f) = so.clicked {
        if k.abs() > 1e-6 {
            return Some(((f.floor() - b as f64) / k as f64).round() as i64);
        }
    }
    None
}

/// 1, 2 or 5 × a power of ten, at least `x`.
fn nice_step(x: f64) -> i64 {
    let mut p = 1i64;
    loop {
        for m in [1, 2, 5] {
            if (m * p) as f64 >= x {
                return m * p;
            }
        }
        p = p.saturating_mul(10);
        if p > 1_000_000_000 {
            return p;
        }
    }
}

fn dist_to_segment(p: egui::Pos2, a: egui::Pos2, b: egui::Pos2) -> f32 {
    let ab = b - a;
    let t = ((p - a).dot(ab) / ab.length_sq().max(1e-6)).clamp(0.0, 1.0);
    (a + ab * t).distance(p)
}

/// A frame ruler over `view` (frames, left edge to right edge, inclusive
/// cells): ticks and numbered labels at a readable spacing. A drag on it
/// pans. `above`: the ticks hang from the bottom (it sits over its bar).
fn remap_ruler(ui: &mut egui::Ui, view: &mut (f64, f64), above: bool) -> egui::Rect {
    let w = ui.available_width().max(40.0);
    let (rect, resp) = ui.allocate_exact_size(egui::vec2(w, 14.0), egui::Sense::drag());
    let n = (view.1 - view.0 + 1.0).max(1.0);
    let px_per = rect.width() as f64 / n;
    if resp.dragged() {
        let dx = resp.drag_delta().x as f64;
        view.0 -= dx / px_per;
        view.1 -= dx / px_per;
        ui.ctx().set_cursor_icon(egui::CursorIcon::Grabbing);
    } else if resp.hovered() {
        ui.ctx().set_cursor_icon(egui::CursorIcon::Grab);
    }
    let vr = (view.0.round() as i64, view.1.round() as i64);
    let x = |f: f64| imfram::widgets::span::x_of(rect, vr, f + 0.5);
    let painter = ui.painter_at(rect);
    let v = ui.visuals();
    let label = nice_step(56.0 / px_per.max(1e-6)).max(1);
    let minor = (label / 5).max(1);
    let font = egui::FontId::monospace(9.0);
    let (edge, dir) = if above { (rect.max.y, -1.0) } else { (rect.min.y, 1.0) };
    let mut f = vr.0.div_euclid(minor) * minor;
    while f <= vr.1 + minor {
        let xf = x(f as f64);
        if rect.x_range().contains(xf) {
            let major = f.rem_euclid(label) == 0;
            let len = if major { 6.0 } else if px_per * minor as f64 >= 4.0 { 3.0 } else { 0.0 };
            if len > 0.0 {
                painter.line_segment(
                    [egui::pos2(xf, edge), egui::pos2(xf, edge + dir * len)],
                    egui::Stroke::new(1.0, v.weak_text_color()),
                );
            }
            if major {
                let (pos, align) = if above {
                    (egui::pos2(xf + 2.0, rect.min.y), egui::Align2::LEFT_TOP)
                } else {
                    (egui::pos2(xf + 2.0, rect.max.y), egui::Align2::LEFT_BOTTOM)
                };
                painter.text(pos, align, f.to_string(), font.clone(), v.weak_text_color());
            }
        }
        f += minor;
    }
    resp.on_hover_text("drag to pan · wheel over the bar zooms");
    rect
}

/// Nearest or blend, for the retimers that can land between frames.
fn time_interp_row(ui: &mut egui::Ui, interp: &mut engine::graph::TimeInterp) {
    use engine::graph::TimeInterp;
    ui.horizontal(|ui| {
        ui.label("frames");
        for (name, mode, tip) in [
            ("nearest", TimeInterp::Nearest, "snap to the closest source frame"),
            (
                "blend",
                TimeInterp::Blend,
                "dissolve between the two frames the sub-frame time falls between \
                 — decodes both, so it costs an extra read per branch",
            ),
        ] {
            if ui
                .add(egui::Button::new(egui::RichText::new(name).small()).selected(*interp == mode))
                .on_hover_text(tip)
                .clicked()
            {
                *interp = mode;
            }
        }
    });
}

/// Does the first DPX of a Read's path (file, `####` pattern or directory)
/// carry a log / printing-density transfer in its header?
fn dpx_is_log(path: &str) -> bool {
    let p = Path::new(path);
    let file = if p.is_file() {
        Some(p.to_path_buf())
    } else {
        let dir = if p.is_dir() { p } else { p.parent().unwrap_or(p) };
        std::fs::read_dir(dir).ok().and_then(|rd| {
            let mut v: Vec<_> = rd
                .flatten()
                .map(|e| e.path())
                .filter(|f| f.extension().is_some_and(|e| e.eq_ignore_ascii_case("dpx")))
                .collect();
            v.sort();
            v.into_iter().next()
        })
    };
    let Some(file) = file else { return false };
    let mut head = vec![0u8; 2048];
    let n = std::fs::File::open(&file)
        .and_then(|mut f| std::io::Read::read(&mut f, &mut head))
        .unwrap_or(0);
    engine::dpx::parse_header(&head[..n])
        .is_ok_and(|i| i.transfer == engine::dpx::Transfer::Log)
}

fn migrate_setup_json(val: &mut serde_json::Value) {
    if let Some(nodes) = val
        .get_mut("graph")
        .and_then(|g| g.get_mut("nodes"))
        .and_then(|n| n.as_object_mut())
    {
        for (_, node) in nodes.iter_mut() {
            if let Some(k) = node.get_mut("kind") {
                if k.as_str() == Some("Merge") {
                    *k = serde_json::json!({ "Merge": {} });
                }
                // A 2dini's Merge was a unit variant with two inputs; it
                // counts its inputs now.
                if let Some(gn) = k
                    .get_mut("Geo")
                    .and_then(|g| g.get_mut("graph"))
                    .and_then(|g| g.get_mut("nodes"))
                    .and_then(|n| n.as_object_mut())
                {
                    for (_, v) in gn.iter_mut() {
                        if v.as_str() == Some("Merge") {
                            *v = serde_json::json!({ "Merge": { "count": 2 } });
                        }
                    }
                }
                // TimeWarp was a speed + start pair before the split into
                // Speed (a constant rate) and TimeRemap (an animated frame).
                // Both old forms have an exact equivalent, so old setups keep
                // their timing: a pure shift is a Slip, anything else is a
                // Speed about the frame that stayed put.
                if let Some(tw) = k.get("TimeWarp").cloned() {
                    let speed = tw.get("speed").and_then(|v| v.as_f64()).unwrap_or(1.0);
                    let start = tw.get("start").and_then(|v| v.as_f64()).unwrap_or(0.0);
                    *k = if (speed - 1.0).abs() < 1e-3 {
                        serde_json::json!({ "Slip": { "offset": start.round() as i64 } })
                    } else {
                        serde_json::json!({
                            "Speed": { "speed": speed, "anchor": start / (1.0 - speed) }
                        })
                    };
                }
            }
        }
    }
    // FRAME NUMBERING (setup v3). Until v2 a tick was an index into the
    // comp range: tick 0 WAS `range.0`, and keyframes were authored in
    // those ticks. Frames are absolute now, so a shot whose range starts
    // above zero has to have its keys moved to the frames they were always
    // meant to mean — otherwise the animation sits before the shot and
    // reads as frozen.
    let version = val.get("version").and_then(|v| v.as_u64()).unwrap_or(0);
    // DPX DECODE (setup v4). The DPX reader used to linearise log-flagged
    // files itself, so an old setup's DPX Read sat on `Working` and still
    // looked right. It now hands back code values like every other reader,
    // so the same Read gets the Cineon input transform the decoder used to
    // apply — same curve (`color::cineon_to_linear`), picture unchanged.
    // Only files whose HEADER says log: a linear/video-flagged DPX was raw
    // codes before and still is.
    if version < 4 {
        if let Some(nodes) = val
            .get_mut("graph")
            .and_then(|g| g.get_mut("nodes"))
            .and_then(|n| n.as_object_mut())
        {
            for (_, node) in nodes.iter_mut() {
                let Some(read) = node.get_mut("kind").and_then(|k| k.get_mut("Read")) else {
                    continue;
                };
                let working = match read.get("input") {
                    None => true,
                    Some(v) => v.as_str() == Some("Working"),
                };
                let Some(path) = read.get("path").and_then(|p| p.as_str()) else { continue };
                if working && colorui::format_of(path) == Some("dpx") && dpx_is_log(path) {
                    if let Ok(v) = serde_json::to_value(engine::color::InputSpace::Explicit(
                        engine::color::Colorspace::CINEON,
                    )) {
                        read["input"] = v;
                    }
                }
            }
        }
    }
    let start = val
        .get("range")
        .and_then(|r| r.as_array())
        .and_then(|r| r.first())
        .and_then(|v| v.as_u64())
        .unwrap_or(0);
    if version < 3 && start > 0 {
        if let Some(nodes) = val
            .get_mut("graph")
            .and_then(|g| g.get_mut("nodes"))
            .and_then(|n| n.as_object_mut())
        {
            for (_, node) in nodes.iter_mut() {
                let Some(anim) = node.get_mut("anim").and_then(|a| a.as_object_mut()) else {
                    continue;
                };
                for (_, chan) in anim.iter_mut() {
                    let Some(keys) = chan.get_mut("keys").and_then(|k| k.as_array_mut())
                    else {
                        continue;
                    };
                    for key in keys.iter_mut() {
                        // Both shapes: the current object and the legacy
                        // `[frame, value]` pair `AnimCurve` still accepts.
                        let f = match key {
                            serde_json::Value::Object(o) => o.get_mut("frame"),
                            serde_json::Value::Array(a) => a.first_mut(),
                            _ => None,
                        };
                        if let Some(f) = f {
                            if let Some(n) = f.as_u64() {
                                *f = serde_json::json!(n + start);
                            }
                        }
                    }
                }
            }
        }
    }
}

/// Longest a Read's first..last range may run. Past the end of the source
/// is deliberate (watching a render arrive), but every frame in it costs a
/// path in the sequence and a tick on the timeline, so it is bounded by
/// something far beyond any real shot rather than by nothing at all.
const MAX_READ_OUT: u64 = 1_000_000;

#[cfg_attr(target_arch = "wasm32", allow(dead_code))] // prefs: localStorage there
fn home_dir() -> Option<std::path::PathBuf> {
    std::env::var("HOME")
        .or_else(|_| std::env::var("USERPROFILE"))
        .ok()
        .map(std::path::PathBuf::from)
}

/// `~/.wobble/prefs.json` — alongside `~/.wobble/plugins`, so everything the
/// app owns in $HOME lives under one directory.
fn prefs_path() -> Option<std::path::PathBuf> {
    home_dir().map(|h| h.join(".wobble/prefs.json"))
}

/// Where prefs lived before the gpu_compositor -> wobble rename. Read as a
/// fallback so an existing install keeps its settings; never written, and
/// never deleted — the first save simply lands at the new path.
fn legacy_prefs_path() -> Option<std::path::PathBuf> {
    home_dir().map(|h| h.join(".gpu_compositor.json"))
}

fn load_prefs() -> Prefs {
    // A page keeps them in localStorage (webmain.rs).
    #[cfg(target_arch = "wasm32")]
    let text = webmain::storage_get(webmain::PREFS_KEY);
    #[cfg(not(target_arch = "wasm32"))]
    let text = prefs_path()
        .and_then(|p| std::fs::read_to_string(p).ok())
        .or_else(|| legacy_prefs_path().and_then(|p| std::fs::read_to_string(p).ok()));
    text.and_then(|s| serde_json::from_str(&s).ok()).unwrap_or_default()
}

/// Set for the whole process when a suite is driving. Suites start from
/// DEFAULT prefs, so letting them save would overwrite the user's real
/// settings with defaults — they read-only.
static TEST_RUN: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
/// `--first-run`: prefs are never written this launch.
static NO_SAVE_PREFS: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

/// UI passes so far, for the suites' watchdog.
static TEST_BEAT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

/// A suite whose frame loop STOPS cannot print its own FAIL line: its
/// wall-clock budget is checked by the very loop that is stuck, so a
/// deadlock read as a suite hanging forever with no output. `--test-zones`
/// and `--test-curveedit` both did, on an egui lock taken inside one of its
/// own closures. This thread notices the UI passes stopping, says so in the
/// battery's `TEST FAIL` form, and exits. 45s is far past anything a suite
/// does inside one pass, and far short of forever.
fn spawn_test_watchdog() {
    use std::sync::atomic::Ordering::Relaxed;
    std::thread::spawn(|| {
        let (mut last, mut still) = (TEST_BEAT.load(Relaxed), 0u32);
        loop {
            std::thread::sleep(web_time::Duration::from_secs(1));
            let now = TEST_BEAT.load(Relaxed);
            if now != last {
                (last, still) = (now, 0);
                continue;
            }
            still += 1;
            if still >= 45 {
                println!(
                    "WATCHDOG TEST FAIL: no UI pass for {still}s — the frame loop is stuck \
                     (a deadlock?); `sample <pid>` while it hangs shows where"
                );
                std::process::exit(1);
            }
        }
    });
}
/// The transport's fixed height: TWO rows — the track, the full window
/// wide, then every control on the row beneath it. Nothing may add a third;
/// `timeline_ui` checks under test that nothing has escaped.
const TIMELINE_H: f32 = 56.0;
/// The track's own height: row one of the transport, the full window wide.
const TRACK_H: f32 = 25.3; // 22 + 15%

/// Scan the plugin directories: `plugins/` beside the working directory
/// (in-repo examples, dev iteration) and `~/.wobble/plugins` (installed).
/// Returns what loaded; errors are logged, never fatal — one broken plugin
/// must not take the app down.
fn load_plugins() -> Vec<String> {
    let mut dirs = vec![std::path::PathBuf::from("plugins")];
    if let Ok(home) = std::env::var("HOME").or_else(|_| std::env::var("USERPROFILE")) {
        dirs.push(std::path::Path::new(&home).join(".wobble/plugins"));
    }
    let mut all = Vec::new();
    // The input proxies a tool body wires its ports to. Registered before
    // any manifest loads, so a body referring to them always resolves.
    tools::register_ports();
    for d in dirs {
        let (loaded, errors) = engine::plugins::load_dir(&d);
        for e in errors {
            log::warn!("plugin: {e}");
        }
        if !loaded.is_empty() {
            log::info!("plugins from {}: {}", d.display(), loaded.join(", "));
        }
        all.extend(loaded);
        // Tools live in the same directories as shader plugins — one place
        // to drop a node into, whichever kind it is — told apart by their
        // manifest filename.
        let (tloaded, terrors) = tools::load_dir(&d);
        for e in terrors {
            log::warn!("subwob: {e}");
        }
        if !tloaded.is_empty() {
            log::info!("subwobs from {}: {}", d.display(), tloaded.join(", "));
        }
        all.extend(tloaded);
    }
    all
}

/// Which part of a control's manipulator is in hand.
#[derive(Clone, Copy, PartialEq, Eq)]
enum PanelGrab {
    /// The handle at its centre: moves the control.
    Move,
    /// An edge handle: scales it, keeping the opposite edge pinned.
    Left,
    Right,
}

/// Viewer 1 held on a node of the graph at dive depth `depth` (0 = the
/// comp). Survives diving in: the render splices every open body back out
/// to that graph and views the node there, so a subwob is edited against
/// the comp's real output.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ViewLock {
    depth: usize,
    node: u64,
    out: u32,
}

/// One level of "inside a tool": everything parked to get here, so stepping
/// back out restores the comp exactly as it was left.
///
/// Diving SWAPS `egraph` rather than pointing the editor at a different
/// graph. Every gesture, every undo step and every panel in the app already
/// works on `self.egraph`, so a swap gives editing-inside-a-tool for free and
/// with no risk of a call site quietly acting on the wrong graph.
/// What a dive is editing. A tool's body is a DEFINITION that lives on disk
/// and is shared by every instance; a noise field belongs to the one node
/// that owns it. They are stepped out of very differently.
#[derive(Clone, Copy, PartialEq, Eq)]
enum DiveKind {
    Tool,
    Noise,
    /// A 2dini geometry graph: owned by its node like a noise field.
    Geo,
    /// An SDF graph: owned by its node the same way.
    Sdf,
    /// A Particles node's emitters, forces and renders, the same way.
    Particles,
    /// A GenAI Pipeline's steps, the same way.
    GenAi,
    /// A Roto's shapes, combines and axes (`rotodive`), the same way.
    Roto,
}

/// The vector HUD's memo inside a 2dini dive: everything the geometry
/// depends on, and the geometry of every node asked for under it.
/// A Physics bake running on a worker: its frames stream in and are shown
/// as they land (the preview plays the partial bake at the newest frame),
/// and the finished bake is written into the node once.
struct PhysicsJob {
    node: u64,
    rx: std::sync::mpsc::Receiver<engine::geophys::BakeMsg>,
    cancel: std::sync::Arc<std::sync::atomic::AtomicBool>,
    /// What has arrived so far.
    bake: Option<engine::geophys::PhysicsBake>,
    /// The same, shared with the preview graph.
    partial: Option<std::sync::Arc<engine::geophys::PhysicsBake>>,
    total: u32,
    /// Where the playhead was, to go back to once it is done.
    return_to: u64,
}

struct GeoHudCache {
    graph: engine::geo::GeoGraph,
    seed: f32,
    /// The tick, when the graph plays a bake (else 0, like the layer's key).
    tick: f32,
    aspect: f32,
    px_per_unit: f32,
    field: Option<engine::geo::FieldCx>,
    geos: Vec<(u64, engine::geo::Geometry)>,
}

struct Dive {
    kind: DiveKind,
    type_id: String,
    /// The instance dived from, when there was one.
    from: Option<u64>,
    /// Panel size in whole tiles, editable in the composer.
    tiles: usize,
    tiles_h: usize,
    /// Where the definition came from, so it is written back in place.
    path: Option<std::path::PathBuf>,
    graph: EditorGraph,
    undo_stack: Vec<EditorGraph>,
    redo_stack: Vec<EditorGraph>,
    undo_last: EditorGraph,
    selected: Vec<u64>,
    zoom: f32,
    pan: egui::Vec2,
}

/// A field graph shown on its own: wrapped in a throwaway Noise node at
/// `size`, at the tick on screen, so authoring sees the field MOVE.
#[allow(clippy::too_many_arguments)]
fn noise_preview_graph(
    field: engine::field::FieldGraph,
    size: (u32, u32),
    scale: f32,
    seed: f32,
    probe: [f32; 2],
    speed: f32,
    speed_unit: f32,
    t: u64,
) -> EditorGraph {
    let mut g = EditorGraph::default();
    let id = 1;
    g.nodes.insert(
        id,
        editor::ENode::new(
            NodeKind::Noise(engine::graph::NoiseParams {
                size,
                inherit: false,
                graph: field,
                scale,
                seed,
                probe,
                speed,
                speed_unit,
                time: t as f32,
                ..Default::default()
            }),
            egui::Pos2::ZERO,
        ),
    );
    g.next_id = id + 1;
    g.view = Some(id);
    g
}

/// A field graph as the node editor holds it: field nodes are ordinary
/// `NodeKind::Field` nodes, which is what lets the WHOLE editor — selection,
/// wiring, undo, the tile layout — work on a noise graph without knowing
/// there is a second data type in the building.
fn field_to_editor(f: &engine::field::FieldGraph) -> EditorGraph {
    let mut g = EditorGraph::default();
    for (i, (id, node)) in f.nodes.iter().enumerate() {
        // A graph authored before layout existed (or built by hand) still
        // has to open: fall back to a readable diagonal.
        let p = f.layout.get(id).copied().unwrap_or([120.0 * i as f32, 60.0 * i as f32]);
        g.nodes.insert(
            *id,
            editor::ENode::new(NodeKind::Field(node.clone()), egui::pos2(p[0], p[1])),
        );
    }
    for ((dst, port), src) in &f.edges {
        g.edges.push((*dst, *port, *src));
    }
    g.view = f.out;
    g.next_id = f.next_id.max(f.nodes.keys().copied().max().unwrap_or(0) + 1);
    g
}

/// The Noise panels' "load a look…" row: picking a stock preset REPLACES the
/// field graph (scale, seed, speed and format are the caller's and stay).
fn noise_preset_row(ui: &mut egui::Ui, id: impl std::hash::Hash + std::fmt::Debug, graph: &mut engine::field::FieldGraph) {
    use engine::field::presets::NoisePreset;
    ui.horizontal(|ui| {
        ui.add_sized([52.0, 16.0], egui::Label::new(egui::RichText::new("preset").small()));
        egui::ComboBox::from_id_salt(("noise-preset", id))
            .selected_text("load a look…")
            // Tall enough for every preset without a scrollbar.
            .height(320.0)
            .show_ui(ui, |ui| {
                for p in NoisePreset::ALL {
                    if ui.selectable_label(false, p.label()).on_hover_text(p.blurb()).clicked() {
                        *graph = p.graph();
                    }
                }
            })
            .response
            .on_hover_text("replaces the field graph with a stock one — scale, seed and speed stay");
    });
}

#[cfg(test)]
mod noise_preset_row_tests {
    /// Not an assertion — a way to LOOK at it: the row with its menu open,
    /// through the real renderer, to `target/noise-presets.png`.
    /// `cargo test -p app noise_preset_menu -- --ignored`
    #[test]
    #[ignore]
    fn noise_preset_menu_shot() {
        let mut g = engine::field::FieldGraph::default();
        let out = crate::uishot::render("noise-presets", 320.0, 400.0, 2.0, 30, |ui, frame| {
            if frame == 1 {
                // The combo is the only clickable thing in the row: open it
                // the way a click would.
                let id = ui.ctx().viewport(|vp| {
                    vp.prev_pass
                        .widgets
                        .layers()
                        .flat_map(|(_, w)| w.iter())
                        .find(|w| w.sense.senses_click() && w.rect.min.x > 40.0 && w.rect.max.y < 40.0)
                        .map(|w| w.id)
                });
                if let Some(id) = id {
                    egui::Popup::open_id(ui.ctx(), id.with("popup"));
                }
            }
            super::noise_preset_row(ui, 1u64, &mut g);
        });
        if let Some(p) = out {
            println!("wrote {}", p.display());
        }
    }
}

/// The other direction, on the way out: everything that is not a field node
/// is dropped, because nothing else can be one.
fn editor_to_field(g: &EditorGraph) -> engine::field::FieldGraph {
    let mut f = engine::field::FieldGraph::default();
    for (id, n) in &g.nodes {
        if let NodeKind::Field(k) = &n.kind {
            f.nodes.insert(*id, k.clone());
            f.layout.insert(*id, [n.pos.x, n.pos.y]);
        }
    }
    for (dst, port, src) in &g.edges {
        if f.nodes.contains_key(dst) && f.nodes.contains_key(src) {
            f.edges.insert((*dst, *port), *src);
        }
    }
    f.out = g.view.filter(|v| f.nodes.contains_key(v));
    f.next_id = g.next_id;
    f
}

/// A geometry graph as the node editor holds it — the field graph's
/// arrangement with the type swapped: every node is a `NodeKind::GeoNode`.
fn geo_to_editor(f: &engine::geo::GeoGraph) -> EditorGraph {
    let mut g = EditorGraph::default();
    for (i, (id, node)) in f.nodes.iter().enumerate() {
        let p = f.layout.get(id).copied().unwrap_or([120.0 * i as f32, 60.0 * i as f32]);
        g.nodes.insert(
            *id,
            editor::ENode::new(NodeKind::GeoNode(node.clone()), egui::pos2(p[0], p[1])),
        );
    }
    for ((dst, port), src) in &f.edges {
        g.edges.push((*dst, *port, *src));
    }
    g.wire_layer = f.wires.clone();
    g.view = f.out;
    g.next_id = f.next_id.max(f.nodes.keys().copied().max().unwrap_or(0) + 1);
    g
}

/// The other direction: everything that is not a geometry node is dropped.
/// Authored values, curves ignored — what the 2dini STORES (its curves ride
/// on the owner, see `geo_curves_out`).
fn editor_to_geo(g: &EditorGraph) -> engine::geo::GeoGraph {
    editor_to_geo_at(g, None)
}

/// `editor_to_geo` with each node's curves evaluated at `t`: the drawing as
/// it is at that frame (a keyed bone turn posed, a keyed width applied).
fn editor_to_geo_at(g: &EditorGraph, t: Option<u64>) -> engine::geo::GeoGraph {
    let mut f = engine::geo::GeoGraph::default();
    for (id, n) in &g.nodes {
        if let NodeKind::GeoNode(k) = &n.kind {
            let k = match t {
                Some(t) if !n.anim.is_empty() => match n.kind_at(t) {
                    NodeKind::GeoNode(k) => k,
                    _ => k.clone(),
                },
                _ => k.clone(),
            };
            f.nodes.insert(*id, k);
            f.layout.insert(*id, [n.pos.x, n.pos.y]);
        }
    }
    for (dst, port, src) in &g.edges {
        if f.nodes.contains_key(dst) && f.nodes.contains_key(src) {
            f.edges.insert((*dst, *port), *src);
        }
    }
    f.wires = g
        .wire_layer
        .iter()
        .filter(|(k, l)| f.edges.contains_key(k) && *l != engine::geo::Layering::default())
        .copied()
        .collect();
    f.out = g.view.filter(|v| f.nodes.contains_key(v));
    f.next_id = g.next_id;
    f
}

/// A 2dini's inner curves, moved off its owner's `anim` (where they live as
/// `inner.<node>.<socket>`, `engine::geo::INNER_PREFIX`) onto the body's
/// nodes as their own `Field` channels — stepping in.
fn geo_curves_in(
    owner: &mut std::collections::BTreeMap<anim::Channel, anim::AnimCurve>,
    body: &mut EditorGraph,
) {
    let inner: Vec<anim::Channel> = owner
        .keys()
        .filter(|c| matches!(c, anim::Channel::Custom(i) if engine::geo::parse_inner(&anim::interned(*i)).is_some()))
        .copied()
        .collect();
    for ch in inner {
        let Some(curve) = owner.remove(&ch) else { continue };
        let anim::Channel::Custom(i) = ch else { continue };
        let Some((node, sock)) = engine::geo::parse_inner(&anim::interned(i)) else { continue };
        if let Some(n) = body.node_mut(node) {
            n.anim.insert(anim::Channel::Field(sock as u16), curve);
        }
    }
}

/// Stepping out: every geometry node's curves back onto the owner, replacing
/// whatever inner curves it carried.
fn geo_curves_out(
    owner: &mut std::collections::BTreeMap<anim::Channel, anim::AnimCurve>,
    body: &EditorGraph,
) {
    owner.retain(|c, _| !matches!(c, anim::Channel::Custom(i) if engine::geo::parse_inner(&anim::interned(*i)).is_some()));
    for (id, n) in &body.nodes {
        if !matches!(n.kind, NodeKind::GeoNode(_)) {
            continue;
        }
        for (ch, curve) in &n.anim {
            if let anim::Channel::Field(sock) = ch {
                let name = engine::geo::inner_channel(*id, *sock as usize);
                owner.insert(anim::Channel::Custom(anim::intern(&name)), curve.clone());
            }
        }
    }
}

/// Where a tool's manifest belongs: back where it came from if it was loaded
/// from a file, else the user's own tool directory.
fn tool_path(id: &str, known: Option<&std::path::Path>) -> std::path::PathBuf {
    if let Some(p) = known {
        return p.to_path_buf();
    }
    std::env::var("HOME")
        .or_else(|_| std::env::var("USERPROFILE"))
        .map(|h| std::path::Path::new(&h).join(".wobble/plugins"))
        .unwrap_or_else(|_| std::path::PathBuf::from("plugins"))
        .join(id)
        .join("tool.json")
}

/// Draw a tool's panel: the CONTROL NODES inside its body, at their cells on
/// the panel's grid.
///
/// There is no separate layout to keep in step with a schema — the controls
/// in the graph ARE the panel, and a knob cannot exist without one.
///
/// Free function, not a method: the caller is already holding `&mut` borrows
/// of the node's kind and its animation map, so `&mut self` is out of reach
/// here — the same reason every other properties arm works off `RowCtx`.

/// Does this node draw controls ON THE VIEWER — transform handles, corner
/// pins, warp grids, spline points? Exactly the kinds the viewer's
/// manipulator pass serves from the pinned-plus-selected set; Paint is not
/// one (its brush follows selection only), so it gets no pin toggle.
/// Tension for the points picked in the viewer, on a Catmull-Rom curve:
/// one slider showing the first picked point's value and writing all of
/// them. The same row in every spline panel (comp Spline, field Roto,
/// 2dini Spline and Stroke), since the curve is the same curve.
fn tension_row(
    ui: &mut egui::Ui,
    points: &mut [engine::graph::SplinePoint],
    mode: engine::graph::SplineMode,
    picked: &[usize],
) {
    if mode != engine::graph::SplineMode::CatmullRom || points.is_empty() {
        return;
    }
    let picked: Vec<usize> = picked.iter().copied().filter(|k| *k < points.len()).collect();
    if picked.is_empty() {
        ui.weak("tension: pick points in the viewer, or K-drag one");
        return;
    }
    let mut t = points[picked[0]].tension;
    if widgets::plain_slider(ui, "tension", &mut t, -1.0, 1.0, false)
        .on_hover_text("how tightly the curve turns at the picked points: 0 smooth, 1 a corner, below 0 rounder")
        .changed()
    {
        for k in &picked {
            points[*k].tension = t;
        }
    }
}

/// What a click on a shape made by `src` selects, viewing `out`: the
/// first Transform upstream of the merge it was combined in, on that
/// shape's own branch; else the shape's maker. "First upstream" walks from
/// the merge toward the maker, so the Transform nearest the merge — the
/// one that places the branch — wins.
fn geo_click_target(g: &engine::geo::GeoGraph, out: u64, src: u64) -> u64 {
    use engine::geo::GeoNode as G;
    // The chain from `out` up to `src` along geometry inputs (DFS; graphs
    // are small and acyclic).
    fn path(g: &engine::geo::GeoGraph, at: u64, src: u64, seen: &mut Vec<u64>) -> Option<Vec<u64>> {
        if at == src {
            return Some(vec![at]);
        }
        if seen.contains(&at) {
            return None;
        }
        seen.push(at);
        let k = g.nodes.get(&at)?;
        for (i, inp) in k.inputs().iter().enumerate() {
            if inp.kind != engine::graph::PortKind::Geo {
                continue;
            }
            if let Some(up) = g.input_of(at, i) {
                if let Some(mut p) = path(g, up, src, seen) {
                    p.push(at);
                    return Some(p);
                }
            }
        }
        None
    }
    let Some(chain) = path(g, out, src, &mut Vec::new()) else { return src };
    // chain runs maker .. out. The merge nearest the maker is where this
    // shape met the others.
    let Some(m) = chain.iter().position(|n| {
        matches!(g.nodes.get(n), Some(G::Merge { .. } | G::Boolean { .. } | G::Instance { .. }))
    }) else {
        return src;
    };
    chain[..m]
        .iter()
        .rev()
        .find(|n| matches!(g.nodes.get(n), Some(G::Transform { .. })))
        .copied()
        .unwrap_or(src)
}

/// Take the `WOBBLE_SHOT` now, whatever its frame count (a suite that
/// wants its own finished state on the picture).
static SHOT_NOW: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

/// Ruler ticks for `scr` screen points per output pixel: a fine step (in
/// output pixels) no closer than 8 points apart, and a labelled one five
/// times it.
fn ruler_steps(scr: f32) -> (f32, f32) {
    let steps = [1.0f32, 2.0, 5.0, 10.0, 20.0, 50.0, 100.0, 200.0, 500.0, 1000.0, 2000.0, 5000.0];
    let minor = steps.iter().copied().find(|s| s * scr >= 8.0).unwrap_or(10000.0);
    (minor, minor * 5.0)
}

/// An Edit node gesture: moving the picked points, or a box being drawn.
/// A bone gesture on a selected Skeleton: a TURN (the bone's pose at the
/// press, the joint it turns about on screen) or, with alt, a REST move of
/// a joint (the bones as they were). Both measured from the press.
#[derive(Clone)]
struct BoneDrag {
    node: u64,
    bone: usize,
    origin: egui::Pos2,
    pivot: egui::Pos2,
    pose0: f32,
    /// Some: a rest move — the bones at the press, and whether it is the
    /// root's head (the whole rig moves) or a bone's tail (that joint).
    rest: Option<(Vec<engine::georig::Bone>, bool)>,
}

#[derive(Clone, Debug)]
enum GeoEditDrag {
    Move { node: u64, origin: egui::Pos2, start: Vec<engine::geo::PointEdit> },
    Box { node: u64, origin: egui::Pos2 },
}

/// `edits` with the picked keys moved `d` past where `start` had them.
fn edits_moved(start: &[engine::geo::PointEdit], pick: &[(u32, u32)], d: [f32; 2]) -> Vec<engine::geo::PointEdit> {
    let mut out: Vec<engine::geo::PointEdit> = start.to_vec();
    for &(prim, vert) in pick {
        let o = start.iter().find(|e| e.prim == prim && e.vert == vert).map_or([0.0, 0.0], |e| e.offset);
        let to = [o[0] + d[0], o[1] + d[1]];
        match out.iter_mut().find(|e| e.prim == prim && e.vert == vert) {
            Some(e) => e.offset = to,
            None => out.push(engine::geo::PointEdit { prim, vert, offset: to }),
        }
    }
    out.retain(|e| e.offset != [0.0, 0.0]);
    out.sort_by_key(|e| (e.prim, e.vert));
    out
}

/// The 2dini tool bar's tools, top to bottom.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum GeoTool {
    Transform,
    Circle,
    Rectangle,
    Polygon,
    Star,
    Text,
    Line,
    Spline,
    Brush,
    /// Direct select: an Edit node after the selection, its points live.
    Direct,
    /// The fill and stroke swatches (not in `ALL`: drawn apart).
    Fill,
    StrokeColour,
}

impl GeoTool {
    const ALL: [GeoTool; 10] = [
        GeoTool::Transform,
        GeoTool::Direct,
        GeoTool::Circle,
        GeoTool::Rectangle,
        GeoTool::Polygon,
        GeoTool::Star,
        GeoTool::Text,
        GeoTool::Line,
        GeoTool::Spline,
        GeoTool::Brush,
    ];

    fn tip(self) -> &'static str {
        match self {
            GeoTool::Transform => "transform the selected shape (a Transform after it)",
            GeoTool::Circle => "circle: drag out from its centre",
            GeoTool::Rectangle => "rectangle: drag corner to corner",
            GeoTool::Polygon => "polygon: drag out from its centre",
            GeoTool::Star => "star: drag out from its centre",
            GeoTool::Text => "text: click where it starts, drag down to size it",
            GeoTool::Line => "line: a new stroke, S-click to lay its points",
            GeoTool::Spline => "spline: a new shape, S-click to lay its points",
            GeoTool::Brush => "brush: a new Brush; drag in the viewer to paint (any Brush selected paints)",
            GeoTool::Direct => "edit points: drag a shape's points by hand (an Edit node after it); shift-click picks more, a drag on nothing boxes them, alt-click puts one back",
            GeoTool::Fill => "fill colour",
            GeoTool::StrokeColour => "stroke colour",
        }
    }

    /// The node the tool makes, from the add menu's own constructors so
    /// the defaults live in one place.
    fn make(self) -> engine::geo::GeoNode {
        let label = match self {
            GeoTool::Transform => "Transform",
            GeoTool::Circle => "Circle",
            GeoTool::Rectangle => "Rectangle",
            GeoTool::Polygon => "Polygon",
            GeoTool::Star => "Star",
            GeoTool::Text => "Text",
            GeoTool::Line => "Stroke",
            GeoTool::Spline => "Spline",
            GeoTool::Brush => "Brush",
            GeoTool::Fill | GeoTool::StrokeColour => "Style",
            GeoTool::Direct => "Edit",
        };
        editor::node_catalog()
            .into_iter()
            .find(|e| e.cat.is_geo() && e.label == label)
            .and_then(|e| match (e.make)(0) {
                NodeKind::GeoNode(k) => Some(k),
                _ => None,
            })
            .unwrap_or_default()
    }
}

/// A shape drawn with a tool, from the press `a` to the pointer `b` (geo
/// space): centred on the press and as big as the drag, or a rectangle
/// corner to corner. A drag of nothing keeps the default size.
fn geo_tool_place(mut k: engine::geo::GeoNode, a: [f32; 2], b: [f32; 2]) -> engine::geo::GeoNode {
    use engine::geo::GeoNode as G;
    let d = ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt();
    let sized = d > 1e-6;
    match &mut k {
        G::Circle { center, radius, .. } | G::Polygon { center, radius, .. } => {
            *center = a;
            if sized {
                *radius = d;
            }
        }
        G::Star { center, outer, inner, .. } => {
            *center = a;
            if sized {
                *inner *= d / outer.max(1e-6);
                *outer = d;
            }
        }
        G::Rectangle { center, size, .. } => {
            if sized {
                *center = [(a[0] + b[0]) * 0.5, (a[1] + b[1]) * 0.5];
                *size = [(b[0] - a[0]).abs(), (b[1] - a[1]).abs()];
            } else {
                *center = a;
            }
        }
        G::Text { position, size, .. } => {
            *position = a;
            if (b[1] - a[1]).abs() > 1e-6 {
                *size = (b[1] - a[1]).abs();
            }
        }
        _ => {}
    }
    k
}

/// A tool's icon, drawn into `r`.
fn geo_tool_icon(p: &egui::Painter, r: egui::Rect, t: GeoTool, col: egui::Color32) {
    let st = egui::Stroke::new(1.4, col);
    let c = r.center();
    let h = r.height().min(r.width()) * 0.5;
    let ring = |n: usize, rad: &dyn Fn(usize) -> f32| -> Vec<egui::Pos2> {
        (0..n)
            .map(|k| {
                let a = -std::f32::consts::FRAC_PI_2 + k as f32 * std::f32::consts::TAU / n as f32;
                c + egui::vec2(a.cos(), a.sin()) * rad(k)
            })
            .collect()
    };
    match t {
        GeoTool::Transform => {
            // A box with its four corner handles and a centre dot.
            let b = egui::Rect::from_center_size(c, egui::vec2(h * 1.5, h * 1.5));
            p.rect_stroke(b, 0.0, st, egui::StrokeKind::Middle);
            for q in [b.left_top(), b.right_top(), b.left_bottom(), b.right_bottom()] {
                p.rect_filled(egui::Rect::from_center_size(q, egui::vec2(3.5, 3.5)), 0.0, col);
            }
            p.circle_filled(c, 1.8, col);
        }
        GeoTool::Circle => {
            p.circle_stroke(c, h * 0.9, st);
        }
        GeoTool::Rectangle => {
            p.rect_stroke(egui::Rect::from_center_size(c, egui::vec2(h * 2.0, h * 1.3)), 2.0, st, egui::StrokeKind::Middle);
        }
        GeoTool::Polygon => {
            p.add(egui::Shape::closed_line(ring(6, &|_| h * 0.95), st));
        }
        GeoTool::Star => {
            p.add(egui::Shape::closed_line(ring(10, &|k| if k % 2 == 0 { h } else { h * 0.45 }), st));
        }
        GeoTool::Text => {
            p.text(c, egui::Align2::CENTER_CENTER, "T", egui::FontId::proportional(h * 2.0), col);
        }
        GeoTool::Line => {
            p.line_segment([r.left_bottom(), r.right_top()], st);
        }
        GeoTool::Fill | GeoTool::StrokeColour => {}
        GeoTool::Direct => {
            // The direct-select arrow: hollow, over a point.
            let pts = vec![
                r.left_top(),
                r.left_top() + egui::vec2(0.0, r.height() * 0.85),
                r.left_top() + egui::vec2(r.width() * 0.3, r.height() * 0.62),
                r.left_top() + egui::vec2(r.width() * 0.62, r.height() * 0.62),
            ];
            p.add(egui::Shape::closed_line(pts, st));
            p.rect_filled(egui::Rect::from_center_size(r.right_bottom() - egui::vec2(3.0, 3.0), egui::vec2(5.0, 5.0)), 0.0, col);
        }
        GeoTool::Brush => {
            // A tapered stroke: thin, fat, thin.
            for k in 0..12 {
                let u = k as f32 / 11.0;
                let q = egui::pos2(r.left() + u * r.width(), r.bottom() - u * r.height() * 0.8 - (u * 3.0).sin() * 2.0);
                p.circle_filled(q, 0.6 + 1.8 * (u * std::f32::consts::PI).sin(), col);
            }
        }
        GeoTool::Spline => {
            let pts: Vec<egui::Pos2> = (0..=16)
                .map(|k| {
                    let u = k as f32 / 16.0;
                    egui::pos2(r.left() + u * r.width(), c.y - (u * std::f32::consts::TAU).sin() * h * 0.7)
                })
                .collect();
            p.add(egui::Shape::line(pts, st));
        }
    }
}

/// A 2dini style's gradient fill: flat / linear / radial / from edges, the
/// colour it runs to, and (from edges) how far in. Linear and radial are
/// placed with the two handles in the viewer.
fn geo_gradient_rows(
    ui: &mut egui::Ui,
    node: u64,
    salt: &str,
    st: &mut engine::geo::Style,
    working: engine::color::Colorspace,
) {
    use engine::geo::GradKind;
    let g = &mut st.grad;
    ui.horizontal(|ui| {
        ui.add_sized([52.0, 16.0], egui::Label::new(egui::RichText::new("gradient").small()));
        egui::ComboBox::from_id_salt((salt, "grad", node))
            .width(96.0)
            .selected_text(g.kind.name())
            .show_ui(ui, |ui| {
                for k in GradKind::ALL {
                    ui.selectable_value(&mut g.kind, k, k.name());
                }
            });
        if g.kind != GradKind::None {
            ui.label(egui::RichText::new("mix").small());
            egui::ComboBox::from_id_salt((salt, "grad-mix", node))
                .width(64.0)
                .selected_text(if g.lch { "lch" } else { "linear" })
                .show_ui(ui, |ui| {
                    ui.selectable_value(&mut g.lch, false, "linear");
                    ui.selectable_value(&mut g.lch, true, "lch");
                })
                .response
                .on_hover_text("linear: the numbers mixed, the way light mixes · lch: lightness, chroma and hue mixed, so the middle keeps its colour");
        }
    });
    if g.kind == GradKind::None {
        return;
    }
    // The Gradient node's own ramp editor, on this style's stops: click the
    // bar to add a stop, drag one to slide it, alt-click to remove it.
    let spec = pick_spec(working, true);
    let mut r = g.ramp(st.fill);
    let before = r.clone();
    let out = nodes::gradient::ramp_editor(ui, node, &mut r, working, &spec);
    let n = r.stops.len();
    let sel = nodes::gradient::selected(ui.ctx(), node, n);
    let mut remove = out.remove;
    if let Some(s) = r.stops.get(sel).copied() {
        ui.horizontal(|ui| {
            ui.label(egui::RichText::new(format!("stop {}/{}", sel + 1, n)).small());
            let mut c = s.color;
            if colorpicker::button(ui, (node, salt, "grad-stop", sel), &mut c, spec).changed() {
                r.stops[sel].color = c;
            }
            if ui.add_enabled(n > 2, egui::Button::new("remove")).on_hover_text("alt-click a stop does the same").clicked() {
                remove = Some(sel);
            }
            if ui.button("reverse").on_hover_text("mirror every stop along the ramp").clicked() {
                for s in r.stops.iter_mut() {
                    s.pos = 1.0 - s.pos;
                }
            }
        });
        let mut pos = r.stops[sel].pos;
        widgets::plain_slider(ui, "position", &mut pos, 0.0, 1.0, false);
        if let Some(s) = r.stops.get_mut(sel) {
            s.pos = pos;
        }
    }
    if let Some(i) = remove.filter(|_| r.stops.len() > 2) {
        r.stops.remove(i);
        nodes::gradient::select(ui.ctx(), node, i.saturating_sub(1));
    }
    if r != before {
        g.set_ramp(&r);
    }
    match g.kind {
        GradKind::Edge => {
            widgets::plain_slider(ui, "depth", &mut g.depth, 1.0, 400.0, false);
            ui.weak("the ramp's start on the outline, its end this many px in");
        }
        _ => {
            ui.weak("drag its two handles in the viewer: where the ramp starts and ends");
        }
    }
}

/// The style a 2dini node draws with, to edit in place.
fn geo_style_mut(k: &mut engine::geo::GeoNode) -> Option<&mut engine::geo::Style> {
    use engine::geo::GeoNode as G;
    match k {
        G::Spline { style, .. }
        | G::Text { style, .. }
        | G::Polygon { style, .. }
        | G::Star { style, .. }
        | G::Circle { style, .. }
        | G::Rectangle { style, .. }
        | G::Style { style } => Some(style),
        _ => None,
    }
}

/// Where a 2dini node's on-screen handles sit: its pivot (geo space) and
/// how they are turned. Every shape generator has one — its centre — and
/// so does a Transform (its pivot, carried by its translate).
#[derive(Clone, Copy, Debug, PartialEq)]
struct GeoFrame {
    centre: [f32; 2],
    rot: f32,
    /// Has a rotation to turn (a circle does not).
    turns: bool,
}

/// One handle drag, as a change from the press.
#[derive(Clone, Copy, Debug, PartialEq)]
enum GeoEdit {
    Move([f32; 2]),
    /// Alt on the centre: move the pivot, leave the shape where it is.
    Pivot([f32; 2]),
    Rotate(f32),
    /// Factors along the frame's own x and y.
    Scale([f32; 2]),
}

/// A handle drag in flight: what was pressed, and the node AS IT WAS, so
/// every frame computes from the press rather than adding to itself.
#[derive(Clone, Debug)]
struct GeoXfDrag {
    node: u64,
    handle: u8,
    origin: egui::Pos2,
    start: engine::geo::GeoNode,
    frame: GeoFrame,
    base: [f32; 2],
}

/// The handle frame of a 2dini node, if it has handles. `base` is the
/// pivot an inheriting Transform is fed.
fn geo_frame(k: &engine::geo::GeoNode, base: [f32; 2]) -> Option<GeoFrame> {
    use engine::geo::GeoNode as G;
    let f = |centre: [f32; 2], rot: f32, turns: bool| Some(GeoFrame { centre, rot, turns });
    match k {
        G::Transform { translate, rotate, pivot, .. } => f(
            [base[0] + pivot[0] + translate[0], base[1] + pivot[1] + translate[1]],
            *rotate,
            true,
        ),
        G::Polygon { center, rotation, .. }
        | G::Star { center, rotation, .. }
        | G::Rectangle { center, rotation, .. } => f(*center, *rotation, true),
        G::Circle { center, .. } => f(*center, 0.0, false),
        G::Text { position, rotation, .. } => f(*position, *rotation, true),
        // Drawn shapes: about the middle of their points, unturned (they
        // have no rotation of their own; a turn moves the points).
        G::Spline { points, .. } | G::Stroke { points, .. } => {
            mid_of(points.iter().map(|q| q.p)).and_then(|c| f(c, 0.0, true))
        }
        G::Brush { strokes, .. } => {
            mid_of(strokes.iter().flat_map(|s| s.pts.iter().map(|p| [p[0], p[1]]))).and_then(|c| f(c, 0.0, true))
        }
        _ => None,
    }
}

/// The middle of a set of points' bounds.
fn mid_of(pts: impl Iterator<Item = [f32; 2]>) -> Option<[f32; 2]> {
    let mut b: Option<([f32; 2], [f32; 2])> = None;
    for p in pts {
        b = Some(match b {
            None => (p, p),
            Some((lo, hi)) => ([lo[0].min(p[0]), lo[1].min(p[1])], [hi[0].max(p[0]), hi[1].max(p[1])]),
        });
    }
    b.map(|(lo, hi)| [(lo[0] + hi[0]) * 0.5, (lo[1] + hi[1]) * 0.5])
}

/// Move / turn / scale a drawn shape's points about `c`: positions turn
/// and scale about it, Bezier handles (offsets) turn and scale with them.
fn edit_points(pts: &mut [[f32; 2]], offsets: &mut [[f32; 2]], c: [f32; 2], e: GeoEdit) {
    let lin = |v: [f32; 2]| -> [f32; 2] {
        match e {
            GeoEdit::Rotate(r) => {
                let (sn, cs) = r.sin_cos();
                [cs * v[0] - sn * v[1], sn * v[0] + cs * v[1]]
            }
            GeoEdit::Scale(f) => [v[0] * f[0], v[1] * f[1]],
            _ => v,
        }
    };
    for p in pts.iter_mut() {
        match e {
            GeoEdit::Move(d) | GeoEdit::Pivot(d) => *p = [p[0] + d[0], p[1] + d[1]],
            _ => {
                let v = lin([p[0] - c[0], p[1] - c[1]]);
                *p = [c[0] + v[0], c[1] + v[1]];
            }
        }
    }
    for o in offsets.iter_mut() {
        *o = lin(*o);
    }
}

/// `start` with one handle drag applied.
fn geo_frame_apply(start: &engine::geo::GeoNode, base: [f32; 2], e: GeoEdit) -> engine::geo::GeoNode {
    use engine::geo::GeoNode as G;
    let mut k = start.clone();
    let mv = |c: &mut [f32; 2], d: [f32; 2]| *c = [c[0] + d[0], c[1] + d[1]];
    match (&mut k, e) {
        (G::Spline { points, .. }, e) | (G::Stroke { points, .. }, e) => {
            let Some(c) = mid_of(points.iter().map(|q| q.p)) else { return k };
            let mut ps: Vec<[f32; 2]> = points.iter().map(|q| q.p).collect();
            let mut hs: Vec<[f32; 2]> = points.iter().flat_map(|q| [q.h_in, q.h_out]).collect();
            edit_points(&mut ps, &mut hs, c, e);
            for (i, q) in points.iter_mut().enumerate() {
                q.p = ps[i];
                q.h_in = hs[2 * i];
                q.h_out = hs[2 * i + 1];
            }
        }
        (G::Brush { strokes, width, .. }, e) => {
            let Some(c) = mid_of(strokes.iter().flat_map(|s| s.pts.iter().map(|p| [p[0], p[1]]))) else { return k };
            for s in strokes.iter_mut() {
                let mut ps: Vec<[f32; 2]> = s.pts.iter().map(|p| [p[0], p[1]]).collect();
                edit_points(&mut ps, &mut [], c, e);
                for (p, q) in s.pts.iter_mut().zip(ps) {
                    p[0] = q[0];
                    p[1] = q[1];
                }
            }
            if let GeoEdit::Scale(f) = e {
                *width *= one_factor(f);
            }
        }
        (G::Transform { translate, pivot, rotate, scale, .. }, GeoEdit::Pivot(d)) => {
            // Move the pivot, and the translate the other way by what the
            // pivot's own motion would do, so the shape stays put.
            let _ = base;
            let (sn, cs) = rotate.sin_cos();
            let m = [[cs * scale[0], -sn * scale[1]], [sn * scale[0], cs * scale[1]]];
            let md = [m[0][0] * d[0] + m[0][1] * d[1], m[1][0] * d[0] + m[1][1] * d[1]];
            *pivot = [pivot[0] + d[0], pivot[1] + d[1]];
            *translate = [translate[0] - (d[0] - md[0]), translate[1] - (d[1] - md[1])];
        }
        (_, GeoEdit::Pivot(d)) | (_, GeoEdit::Move(d)) => match &mut k {
            G::Transform { translate, .. } => mv(translate, d),
            G::Polygon { center, .. }
            | G::Star { center, .. }
            | G::Circle { center, .. }
            | G::Rectangle { center, .. } => mv(center, d),
            G::Text { position, .. } => mv(position, d),
            _ => {}
        },
        (G::Transform { rotate, .. }, GeoEdit::Rotate(r))
        | (G::Polygon { rotation: rotate, .. }, GeoEdit::Rotate(r))
        | (G::Star { rotation: rotate, .. }, GeoEdit::Rotate(r))
        | (G::Rectangle { rotation: rotate, .. }, GeoEdit::Rotate(r))
        | (G::Text { rotation: rotate, .. }, GeoEdit::Rotate(r)) => *rotate += r,
        (G::Transform { scale, .. }, GeoEdit::Scale(f)) => *scale = [scale[0] * f[0], scale[1] * f[1]],
        (G::Rectangle { size, corner, .. }, GeoEdit::Scale(f)) => {
            *size = [size[0] * f[0].abs(), size[1] * f[1].abs()];
            *corner *= f[0].abs().min(f[1].abs());
        }
        // One radius: the axis that moved most drives it.
        (G::Polygon { radius, .. }, GeoEdit::Scale(f)) | (G::Circle { radius, .. }, GeoEdit::Scale(f)) => {
            *radius *= one_factor(f)
        }
        (G::Star { outer, inner, .. }, GeoEdit::Scale(f)) => {
            let u = one_factor(f);
            *outer *= u;
            *inner *= u;
        }
        (G::Text { size, .. }, GeoEdit::Scale(f)) => *size *= one_factor(f),
        _ => {}
    }
    k
}

/// A pair of scale factors as one, for a shape with a single size.
fn one_factor(f: [f32; 2]) -> f32 {
    let u = if (f[0] - 1.0).abs() >= (f[1] - 1.0).abs() { f[0] } else { f[1] };
    u.abs()
}

#[cfg(test)]
mod geo_curve_tests {
    use super::*;
    use engine::geo::GeoNode as G;
    use engine::georig::Bone;

    fn skeleton() -> G {
        let b = |parent, head, tail| Bone { name: String::new(), parent, head, tail };
        G::Skeleton { bones: vec![b(None, [0.5, 0.5], [0.5, 0.3]), b(Some(0), [0.5, 0.3], [0.6, 0.2])], pose: vec![0.0, 0.0] }
    }

    fn turn(k: &NodeKind, bone: usize) -> f32 {
        match k {
            NodeKind::Geo(p) => match p.graph.nodes.values().next() {
                Some(G::Skeleton { pose, .. }) => pose[bone],
                _ => panic!("no skeleton"),
            },
            _ => panic!("not a 2dini"),
        }
    }

    /// Bone turns keyed INSIDE a 2dini come out on its node, pose the
    /// drawing per frame there (what the comp renders), and go back onto
    /// the body's nodes on the way in. They used to be dropped at the door.
    #[test]
    fn bone_keys_made_inside_survive_and_animate_outside() {
        let mut body = EditorGraph::default();
        let sk = body.add(NodeKind::GeoNode(skeleton()), egui::pos2(0.0, 0.0));
        let c = body.node_mut(sk).unwrap().anim.entry(anim::Channel::Field(1)).or_default();
        c.set_key(0u64, 0.0);
        c.set_key(10u64, 1.0);
        // Inside: the evaluated graph is posed, the stored one is not.
        let at5 = editor_to_geo_at(&body, Some(5));
        let Some(G::Skeleton { pose, .. }) = at5.nodes.get(&sk) else { panic!() };
        assert!((pose[1] - 0.5).abs() < 1e-4, "posed at 5: {pose:?}");
        // Step out.
        let mut outer = EditorGraph::default();
        let owner = outer.add(NodeKind::Geo(Default::default()), egui::pos2(0.0, 0.0));
        let e = outer.node_mut(owner).unwrap();
        if let NodeKind::Geo(p) = &mut e.kind {
            p.graph = editor_to_geo(&body);
        }
        geo_curves_out(&mut e.anim, &body);
        let n = outer.node(owner).unwrap();
        assert_eq!(turn(&n.kind, 1), 0.0, "the stored pose is unkeyed");
        assert!((turn(&n.kind_at(10), 1) - 1.0).abs() < 1e-4);
        assert!((turn(&n.kind_at(5), 1) - 0.5).abs() < 1e-4);
        assert_eq!(turn(&n.kind_at(5), 0), 0.0, "an unkeyed bone stays put");
        // Back in: on the body's node again, and gone from the owner.
        let mut back = geo_to_editor(match &outer.node(owner).unwrap().kind {
            NodeKind::Geo(p) => &p.graph,
            _ => unreachable!(),
        });
        geo_curves_in(&mut outer.node_mut(owner).unwrap().anim, &mut back);
        assert!(outer.node(owner).unwrap().anim.is_empty());
        let curve = back.node(sk).unwrap().anim.get(&anim::Channel::Field(1)).expect("curve back inside");
        assert_eq!(curve.eval(10), Some(1.0));
    }
}

#[cfg(test)]
mod geo_handle_tests {
    use super::*;
    use engine::geo::{GeoGraph, GeoNode as G, Style};

    fn star() -> G {
        G::Star { center: [0.5, 0.4], outer: 0.1, inner: 0.05, points: 5, rotation: 0.0, style: Style::default() }
    }

    /// A generator's handles sit on its centre and edit its own numbers.
    #[test]
    fn generator_handles_move_turn_and_size_the_shape() {
        let fr = geo_frame(&star(), [0.0, 0.0]).unwrap();
        assert_eq!(fr.centre, [0.5, 0.4]);
        let G::Star { center, .. } = geo_frame_apply(&star(), [0.0; 2], GeoEdit::Move([0.1, 0.0])) else { panic!() };
        assert!((center[0] - 0.6).abs() < 1e-6);
        let G::Star { rotation, .. } = geo_frame_apply(&star(), [0.0; 2], GeoEdit::Rotate(0.5)) else { panic!() };
        assert_eq!(rotation, 0.5);
        let G::Star { outer, inner, .. } = geo_frame_apply(&star(), [0.0; 2], GeoEdit::Scale([2.0, 1.0])) else { panic!() };
        assert!((outer - 0.2).abs() < 1e-6 && (inner - 0.1).abs() < 1e-6, "both radii scale together");
        let rect = G::Rectangle { center: [0.5, 0.5], size: [0.2, 0.1], corner: 0.02, rotation: 0.0, style: Style::default() };
        let G::Rectangle { size, corner, .. } = geo_frame_apply(&rect, [0.0; 2], GeoEdit::Scale([2.0, 3.0])) else { panic!() };
        assert!((size[0] - 0.4).abs() < 1e-6 && (size[1] - 0.3).abs() < 1e-6 && (corner - 0.04).abs() < 1e-6);
        let circle = G::Circle { center: [0.5, 0.5], radius: 0.1, style: Style::default() };
        assert!(!geo_frame(&circle, [0.0; 2]).unwrap().turns, "a circle has nothing to turn");
        assert!(geo_frame(&G::Output, [0.0; 2]).is_none());
    }

    /// An inheriting Transform's handles sit on the shape it is fed.
    #[test]
    fn an_inheriting_transform_sits_on_its_inputs_pivot() {
        let xf = G::Transform { translate: [0.1, 0.0], rotate: 0.0, scale: [1.0, 1.0], pivot: [0.0, 0.0], inherit: true };
        assert_eq!(geo_frame(&xf, [0.5, 0.4]).unwrap().centre, [0.6, 0.4]);
        // Alt-drag on the centre moves the pivot and leaves the shape.
        let G::Transform { translate, pivot, .. } = geo_frame_apply(&xf, [0.5, 0.4], GeoEdit::Pivot([0.05, 0.0])) else { panic!() };
        assert_eq!(pivot, [0.05, 0.0]);
        assert!((translate[0] - 0.1).abs() < 1e-6, "unturned, unscaled: the shape does not move");
    }

    /// Clicking a merged shape picks the Transform that places its branch.
    #[test]
    fn a_click_on_a_merged_shape_picks_its_branchs_transform() {
        let xf = || G::Transform { translate: [0.0; 2], rotate: 0.0, scale: [1.0; 2], pivot: [0.0; 2], inherit: true };
        let mut g = GeoGraph::default();
        g.nodes.insert(1, star());
        g.nodes.insert(2, xf());
        g.nodes.insert(3, xf());
        g.nodes.insert(4, G::default());
        g.nodes.insert(5, G::Merge { count: 3 });
        g.nodes.insert(6, G::Output);
        g.edges.insert((2, 0), 1);
        g.edges.insert((3, 0), 2);
        g.edges.insert((5, 0), 3);
        g.edges.insert((5, 1), 4);
        g.edges.insert((6, 0), 5);
        assert_eq!(geo_click_target(&g, 6, 1), 3, "the Transform nearest the merge");
        assert_eq!(geo_click_target(&g, 6, 4), 4, "no Transform on its branch: the maker");
        // Not merged: the maker, whose own handles move it.
        assert_eq!(geo_click_target(&g, 3, 1), 1);
    }
}

fn has_viewer_hud(kind: &NodeKind) -> bool {
    matches!(
        kind,
        NodeKind::Transform(_)
            | NodeKind::SoftCrop(_)
            | NodeKind::Gradient(_)
            | NodeKind::Mirror(_)
            | NodeKind::Compare(_)
            | NodeKind::LensDistort(_)
            | NodeKind::GridWarp(_)
            | NodeKind::Warp(_)
            | NodeKind::CornerPin(_)
            | NodeKind::Spline(_)
            | NodeKind::Field(engine::field::FieldNode::Spline { .. })
            | NodeKind::GeoNode(engine::geo::GeoNode::Spline { .. })
            | NodeKind::GeoNode(engine::geo::GeoNode::Stroke { .. })
            | NodeKind::SdfNode(engine::sdf::SdfNode::Spline { .. })
    )
}

/// A colour picker for a swatch in THIS comp: previews, lch and hex go
/// through the working space's own matrices, and drags ride the z/x/c/v
/// rate table. The glue that keeps `colorpicker` itself egui-only.
fn pick_spec(working: engine::color::Colorspace, alpha: bool) -> colorpicker::PickSpec {
    use engine::color::{primaries_matrix, Primaries::Rec709};
    let base = if alpha { colorpicker::PickSpec::rgba() } else { colorpicker::PickSpec::rgb() };
    base.with_display(
        primaries_matrix(working.primaries, Rec709),
        primaries_matrix(Rec709, working.primaries),
    )
    .with_input(widgets::sens_factor, widgets::claim_sens)
    .with_eyedrop(eyedrop::pick_hook)
}

#[allow(clippy::too_many_arguments)]
fn tool_panel_ui(
    ui: &mut egui::Ui,
    cx: &mut widgets::RowCtx,
    body: &EditorGraph,
    // The tool's OWN grid. Deriving it from the available rect instead is
    // what made an arrangement come apart the moment it was viewed on an
    // instance: a properties area shorter than the declared panel produced
    // fewer rows, stored cells stopped fitting, and `layout_cells` re-flowed
    // the lot. The grid belongs to the tool; the rect only says where to draw.
    cols: i32,
    rows: i32,
    params: &mut std::collections::BTreeMap<String, f32>,
    ungang: &mut std::collections::BTreeSet<String>,
    working: engine::color::Colorspace,
    zoom: f32,
    // The composer's drag in flight: this control is drawn at this rect
    // (panel-relative, unzoomed) instead of its cell, so it follows the
    // hand per pixel and only snaps on release.
    live: Option<(u64, egui::Rect)>,
) -> Option<widgets::HudSlider> {
    // The grid's own size, allocated explicitly rather than taken from
    // `max_rect`: inside a scroll area `max_rect` is the VIEWPORT, and laying
    // the panel out against that would make it shrink to whatever is on
    // screen instead of scrolling.
    let (panel, _) = ui.allocate_exact_size(
        egui::vec2(
            cols as f32 * tools::CELL_W * zoom,
            rows as f32 * tools::CELL_H * zoom,
        ),
        egui::Sense::hover(),
    );
    let mut out = None;
    let mut any = false;
    for (id, cell, span) in tools::layout_cells(body, cols, rows) {
        let Some(n) = body.node(id) else { continue };
        let Some(k) = tools::control_of(&n.kind) else { continue };
        any = true;
        let r = match live {
            Some((lid, lr)) if lid == id => egui::Rect::from_min_size(
                panel.min + lr.min.to_vec2() * zoom,
                lr.size() * zoom,
            ),
            _ => egui::Rect::from_min_size(
                panel.min
                    + egui::vec2(
                        cell[0] as f32 * tools::CELL_W * zoom,
                        cell[1] as f32 * tools::CELL_H * zoom,
                    ),
                egui::vec2(
                    span[0] as f32 * tools::CELL_W * zoom,
                    span[1] as f32 * tools::CELL_H * zoom,
                ),
            ),
        }
        .intersect(panel);
        if r.width() < 8.0 || r.height() < 8.0 {
            continue;
        }
        // The range this control was configured with, inside the tool, and
        // whether an rgb triple is a MULTIPLIER (gain, gamma) rather than an
        // offset — the slider's colour axes and zero-crossing rule differ.
        let (lo, hi, mult) = match &n.kind {
            NodeKind::Custom { params: cp, .. } => (
                cp.get("lo").copied().unwrap_or(0.0),
                cp.get("hi").copied().unwrap_or(1.0),
                cp.get("scale").copied().unwrap_or(0.0) > 0.5,
            ),
            _ => (0.0, 1.0, false),
        };
        let cap = if n.ui_label.is_empty() {
            k.menu_label().to_string()
        } else {
            n.ui_label.clone()
        };
        // Its OWN id: sibling scopes share one (egui's `Ui::id`), and every
        // wheel's disc is `ui.id().with("disc")` — so on a panel with more
        // than one, only the last took the pointer and all of them moved.
        ui.scope_builder(egui::UiBuilder::new().max_rect(r).id_salt(("panel-control", id)), |ui| match k {
            tools::ControlKind::Label => {
                ui.label(&cap);
            }
            tools::ControlKind::Slider => {
                let name = tools::lane_param(id, k, 0);
                let ch = anim::Channel::Custom(anim::intern(&name));
                let mut v = tools::lane_value(params, &n.kind, k, 0, &name);
                let h = if lo < hi {
                    widgets::slider(ui, cx, &cap, &mut v, lo, hi, &[ch])
                } else {
                    widgets::drags(ui, cx, &cap, &mut [&mut v], 0.01, (lo, hi), &[ch])
                };
                params.insert(name, v);
                if h.is_some() {
                    out = h;
                }
            }
            tools::ControlKind::Pair => {
                let names = [tools::lane_param(id, k, 0), tools::lane_param(id, k, 1)];
                let chans = [
                    anim::Channel::Custom(anim::intern(&names[0])),
                    anim::Channel::Custom(anim::intern(&names[1])),
                ];
                let mut a = tools::lane_value(params, &n.kind, k, 0, &names[0]);
                let mut b = tools::lane_value(params, &n.kind, k, 1, &names[1]);
                // The padlock: UI memory per control, starting as the
                // control says (a scale comes in locked).
                let lid = egui::Id::new(("panel-pair-lock", id));
                let start = matches!(&n.kind, NodeKind::Custom { params: cp, .. } if cp.get("lock").copied().unwrap_or(0.0) > 0.5);
                let mut locked = ui.data(|d| d.get_temp::<bool>(lid)).unwrap_or(start);
                // Pixels step by one, ratios by a hundredth.
                let speed = if hi - lo > 100.0 { 1.0 } else { 0.01 };
                let h = widgets::drags_locked(ui, cx, &cap, &mut [&mut a, &mut b], speed, (lo, hi), &chans, &mut locked);
                ui.data_mut(|d| d.insert_temp(lid, locked));
                params.insert(names[0].clone(), a);
                params.insert(names[1].clone(), b);
                if h.is_some() {
                    out = h;
                }
            }
            tools::ControlKind::Rgb | tools::ControlKind::Wheel => {
                let names: Vec<String> =
                    (0..3).map(|i| tools::lane_param(id, k, i)).collect();
                // Untouched lanes read what the control was authored at —
                // the value the render is already using — never a fixed 1.
                let mut v = [0.0f32; 3];
                for (i, nm) in names.iter().enumerate() {
                    v[i] = tools::lane_value(params, &n.kind, k, i, nm);
                }
                if k == tools::ControlKind::Wheel {
                    // Fit the instrument to its cell. Scaling it by the
                    // properties zoom alone let it overflow a narrow cell or
                    // rattle around in a wide one; its aspect is fixed, so
                    // the cell decides its size.
                    let fit = (r.width() / wheels::COL_W)
                        .min(r.height() / wheels::COL_H)
                        .clamp(0.2, 4.0);
                    // What it was made from says which it is; a wheel made
                    // before that was recorded goes by its name.
                    let wmult = match &n.kind {
                        NodeKind::Custom { params: cp, .. } => cp.get("scale").map(|s| *s > 0.5),
                        _ => None,
                    }
                    .unwrap_or_else(|| {
                        let l = cap.to_lowercase();
                        !(l.contains("lift") || l.contains("offset"))
                    });
                    wheels::bound_wheel_ui(ui, &cap, &mut v, lo, hi, fit, wmult);
                } else {
                    let chans = [
                        anim::Channel::Custom(anim::intern(&names[0])),
                        anim::Channel::Custom(anim::intern(&names[1])),
                        anim::Channel::Custom(anim::intern(&names[2])),
                    ];
                    let mut gang = !ungang.contains(&cap);
                    let luma = working.primaries.luma_weights();
                    let sp = if mult {
                        rgbslider::RgbSpec::scale(lo, hi, luma)
                    } else {
                        rgbslider::RgbSpec::offset(lo, hi, luma)
                    }
                    .with_display(engine::color::primaries_matrix(
                        working.primaries,
                        engine::color::Primaries::Rec709,
                    ));
                    if let Some(h) =
                        widgets::rgb_row(ui, cx, &cap, &mut v, &mut gang, sp, &chans)
                    {
                        out = Some(h);
                    }
                    if gang {
                        ungang.remove(&cap);
                    } else {
                        ungang.insert(cap.clone());
                    }
                }
                for (i, nm) in names.iter().enumerate() {
                    params.insert(nm.clone(), v[i]);
                }
            }
        });
    }
    if !any {
        ui.weak("no controls yet — add a Slider, RGB Slider or Colour Wheel inside the subwob");
    }
    out
}

/// A file-safe type id from a display name: "Soft Clip" -> "soft_clip".
fn tool_type_id(name: &str) -> String {
    name.trim()
        .chars()
        .map(|c| if c.is_ascii_alphanumeric() { c.to_ascii_lowercase() } else { '_' })
        .collect::<String>()
        .trim_matches('_')
        .to_string()
}

/// The quick start guide (source: ~/src/webs/website_wobble). Opened in the
/// browser on first launch and from the help menu.
const QUICKSTART_URL: &str = "https://quickstart.wobble.ing";

/// Open a URL in the system browser, fire and forget.
fn open_url(url: &str) {
    #[cfg(target_arch = "wasm32")]
    let r = webmain::open_url(url);
    #[cfg(target_os = "macos")]
    let r = std::process::Command::new("open").arg(url).spawn();
    #[cfg(target_os = "windows")]
    let r = std::process::Command::new("cmd").args(["/C", "start", "", url]).spawn();
    #[cfg(not(any(target_os = "macos", target_os = "windows", target_arch = "wasm32")))]
    let r = std::process::Command::new("xdg-open").arg(url).spawn();
    if let Err(e) = r {
        log::warn!("opening {url}: {e}");
    }
}

/// Where the Scrub editor's binary should be: beside this executable (a
/// cargo target dir, or the app bundle's `Contents/MacOS`).
#[cfg(not(target_arch = "wasm32"))]
fn scrub_exe() -> std::io::Result<std::path::PathBuf> {
    let exe = std::env::current_exe()?;
    let dir = exe.parent().ok_or_else(|| std::io::Error::other("executable has no directory"))?;
    Ok(dir.join(format!("scrub{}", std::env::consts::EXE_SUFFIX)))
}

impl Gfx {
    /// Start Scrub, the timeline editor, as a process of its own: the
    /// `scrub` binary (`scrub/app`) beside this one, else on PATH. This
    /// comp stays exactly as it is.
    #[cfg(not(target_arch = "wasm32"))]
    fn launch_scrub(&mut self) {
        self.scrub_error = None;
        let beside = scrub_exe();
        let started = match &beside {
            Ok(p) if p.is_file() => std::process::Command::new(p).spawn(),
            _ => std::process::Command::new("scrub").spawn(),
        };
        if let Err(e) = started {
            let looked = beside.map(|p| p.display().to_string()).unwrap_or_else(|_| "beside wobble".into());
            let msg = if e.kind() == std::io::ErrorKind::NotFound {
                format!("scrub is not installed (looked for {looked} and on PATH)")
            } else {
                format!("could not start scrub: {e}")
            };
            log::error!("{msg}");
            self.scrub_error = Some(msg);
        }
    }

    /// Start a take of the window (or the viewer), or stop the running one.
    fn toggle_recording(&mut self, ctx: &egui::Context) {
        if self.recorder.recording() {
            self.recorder.stop(&self.ctx.device);
            return;
        }
        let caps = self.surface.get_capabilities(&self.ctx.adapter);
        if !caps.usages.contains(wgpu::TextureUsages::COPY_SRC) {
            self.recorder.error = Some("this GPU's window surface cannot be copied, so it cannot be recorded".into());
            return;
        }
        let ppp = ctx.pixels_per_point();
        let rect = match self.recorder.opts.area {
            recorder::Area::Window => [0.0, 0.0, self.config.width as f32, self.config.height as f32],
            recorder::Area::Viewer => {
                let r = self.viewer_rect;
                [r.min.x * ppp, r.min.y * ppp, r.width() * ppp, r.height() * ppp]
            }
        };
        self.recorder.start(&self.ctx.device, rect, self.config.width, self.config.height, ppp);
    }

    /// Save one PNG of the window as drawn, on the next redraw.
    fn take_screenshot(&mut self, ctx: &egui::Context) {
        let caps = self.surface.get_capabilities(&self.ctx.adapter);
        if !caps.usages.contains(wgpu::TextureUsages::COPY_SRC) {
            self.shot.note = Some((
                Err("this GPU's window surface cannot be copied, so it cannot be saved".into()),
                web_time::Instant::now(),
            ));
            return;
        }
        self.shot.request();
        ctx.request_repaint();
    }
}

/// The install's random id, made the first time update checks are on (a
/// user who never turns them on never gets one). `None` while they are off.
fn install_id(prefs: &mut Prefs) -> Option<String> {
    if prefs.check_updates != Some(true) {
        return None;
    }
    if prefs.install_id.is_none() {
        use std::hash::{BuildHasher, Hasher};
        // RandomState is seeded from the OS's randomness per instance.
        let word = || {
            let mut h = std::collections::hash_map::RandomState::new().build_hasher();
            h.write_u128(web_time::SystemTime::now().duration_since(web_time::UNIX_EPOCH).map_or(0, |d| d.as_nanos()));
            h.finish()
        };
        prefs.install_id = Some(format!("{:016x}{:016x}", word(), word()));
        save_prefs(prefs);
    }
    prefs.install_id.clone()
}

/// Which build the new-build popup was answered for: its version, or its
/// commit for a manifest without one.
fn update_key(u: &report::Latest) -> &str {
    if u.version.is_empty() { &u.git } else { &u.version }
}

fn save_prefs(p: &Prefs) {
    if TEST_RUN.load(std::sync::atomic::Ordering::Relaxed) || NO_SAVE_PREFS.load(std::sync::atomic::Ordering::Relaxed) {
        return;
    }
    #[cfg(target_arch = "wasm32")]
    if let Ok(s) = serde_json::to_string(p) {
        webmain::storage_set(webmain::PREFS_KEY, &s);
    }
    #[cfg(not(target_arch = "wasm32"))]
    if let (Some(path), Ok(s)) = (prefs_path(), serde_json::to_string_pretty(p)) {
        if let Some(dir) = path.parent() {
            let _ = std::fs::create_dir_all(dir);
        }
        if let Err(e) = std::fs::write(&path, s) {
            log::warn!("saving prefs to {}: {e}", path.display());
        }
    }
}

